// SR-132 read-direction buffer push.
// Normalises the Slack event into the relay's RelayedSlackMessage
// shape and pushes onto a ring buffer of the last 100 messages
// in workflow-global Static Data.
const BUF_KEY = 'slackRelayBuffer';
const BUF_MAX = 100;
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd[BUF_KEY])) sd[BUF_KEY] = [];

// Slack event payload shape varies by event subtype. We only relay
// plain messages from real users; bot/edits/deletes are ignored to
// keep the chat pane uncluttered.
const evt = $json;
const subtype = evt.subtype || null;
if (subtype && subtype !== 'thread_broadcast') {
  return [];
}
if (!evt.ts || !evt.text || !evt.user) return [];

// Display name resolution: Slack returns a user id (UXXX). The
// trigger node may include user_profile depending on settings; if
// not, the relay's polling consumer can fall back to the bare id.
const username =
  evt.user_profile?.display_name ||
  evt.user_profile?.real_name ||
  evt.user_profile?.name ||
  evt.user;

const entry = {
  ts: String(evt.ts),
  user: String(evt.user),
  username: String(username),
  text: String(evt.text),
};
sd[BUF_KEY].push(entry);
if (sd[BUF_KEY].length > BUF_MAX) {
  sd[BUF_KEY] = sd[BUF_KEY].slice(-BUF_MAX);
}
return [{ json: entry }];

// SR-132 read-direction buffer read.
// Returns ring-buffer entries with ts strictly greater than ?since.
// When ?since is omitted or empty, returns the whole buffer (the
// client treats that as 'first poll, get current snapshot').
const BUF_KEY = 'slackRelayBuffer';
const sd = $getWorkflowStaticData('global');
const buf = Array.isArray(sd[BUF_KEY]) ? sd[BUF_KEY] : [];

const input = $input.first()?.json || {};
const sinceRaw = input.query?.since ?? '';
const since = parseFloat(String(sinceRaw));

const filtered = Number.isFinite(since)
  ? buf.filter((m) => parseFloat(m.ts) > since)
  : buf;

return [{ json: { messages: filtered } }];
